import csv, glob, re, sys, urllib.request
bad = []
src = {r['id']: r for r in csv.DictReader(open('kb/public/_sources.csv', encoding='utf-8'))}
census = {r['id']: r for r in csv.DictReader(open('kb/public/_census/2026-10-21.csv', encoding='utf-8'))}
text = {p: open(p, encoding='utf-8').read() for p in glob.glob('kb/public/**/*.md', recursive=True) + glob.glob('kb/public/**/*.csv', recursive=True) if '/_census/' not in p and not p.endswith('_sources.csv') and not p.endswith('_anchors.csv') and not p.endswith('_fetch_state.csv')}
for sid in ('S-c7yqvidh', 'S-f7arhttw', 'S-lpohskwn'):
    o = census[sid]['outcome']
    cited = [p for p, t in text.items() if re.search(r'\b%s\b' % re.escape(sid), t)]
    if o == 'superseded' and cited:
        bad.append('%s is superseded but still cited in %s' % (sid, cited[:3]))
    if o in ('unconfirmed', ''):
        bad.append('%s left %r: record gone or superseded with its cause' % (sid, o))
if 'Cited only by' in census['S-fsqu2grq']['outcome_note']:
    bad.append('S-fsqu2grq note still says it is cited only by the ledgers')
art = open('kb/public/gitlab/job-log-timestamps.md', encoding='utf-8').read().split('\n')
url = src['S-4pm7parz']['url']
req = urllib.request.Request(url, headers={'User-Agent': 'it-ops-kb census check'})
code = urllib.request.urlopen(req, timeout=60).read().decode('utf-8', 'replace').split('\n')
for n in (22, 33):
    seg = re.findall(r'CODE S-4pm7parz: ([^\];]*)', art[n - 1])
    ptrs = [(int(a), int(b or a)) for x in seg for a, b in re.findall(r'flags\.go#L(\d+)(?:-L(\d+))?', x)]
    if not ptrs:
        bad.append('job-log-timestamps.md:%d cites S-4pm7parz with no flags.go line pointer' % n)
    for a, b in ptrs:
        if not any('UseTimestamps' in l for l in code[a - 1:b]):
            bad.append('job-log-timestamps.md:%d points flags.go#L%d-L%d, which at the pin of S-4pm7parz does not hold UseTimestamps' % (n, a, b))
print(len(bad), 'census data defects from the sprint review:', bad)
sys.exit(1 if bad else 0)

